 }finally{Call(minions,"Dispose");Call(bolts,"Dispose");Call(indicators,"Dispose");UnityEngine.Object.DestroyImmediate(bg);UnityEngine.Object.DestroyImmediate(mat);UnityEngine.Object.DestroyImmediate(go);}}
